namespace MiniERP.Desktop.Infrastructure;

/// <summary>
/// Shared external-document brand assets. The official logo is kept as the exact
/// transparent PNG supplied by Forlinx so PDF exporters do not have to approximate
/// the mark with fonts or vector primitives.
/// </summary>
public static class DocumentBrandAssets
{
    private static readonly Lazy<byte[]> ForlinxLogo = new(() => Convert.FromBase64String(ForlinxLogoBase64));

    public static byte[] ForlinxLogoPng => ForlinxLogo.Value;

    private const string ForlinxLogoBase64 =
        "";
}
